package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

/** The signed-in name a change was made by, as the screen sends it in the URI-encoded X-User header. */
public final class AuditUser {

    private AuditUser() {
    }

    public static String decode(String header) {
        return header == null ? "" : URLDecoder.decode(header.replace("+", "%2B"), StandardCharsets.UTF_8).trim();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim's status change, once it is saved, with the claim's number when it has one;
 * a settle or approve adds the due it fixed (n/a when the grade had no rate), a reject its reason. */
public class AuditClaimStatus {
    public void audit(@Parameter String number, @Val Claim claim, PersonRepository people,
            @PathVariable("action") String action,
            @RequestParam(name = "reason", required = false) String reason,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        String event = switch (action) {
            case "approve" -> "CLAIM_APPROVED";
            case "reject" -> "CLAIM_REJECTED";
            default -> claim.getStatus().event();
        };
        String line = ClaimAudit.line(event, claim, person, AuditUser.decode(user), number);
        if ("reject".equals(action)) {
            line += " reason=" + reason.trim();
        }
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getDue() == null ? "n/a" : claim.getDue().setScale(2).toPlainString());
        }
        audit.record(line);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the re-settle, once it is saved: the claim's line, then the due it had and the one it has now. */
public class AuditClaimResettled {
    public void audit(@Parameter Resettled resettled, @Val Claim claim, PersonRepository people,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        audit.record(ClaimAudit.line("CLAIM_RESETTLED", claim, person, AuditUser.decode(user))
                + " old=" + shown(resettled.old()) + " new=" + shown(resettled.now()));
    }

    private static String shown(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

/** A claim's audit line: the event, sheet, user, person, amount as the screen shows it, date, and the claim's
 * number when it has one. */
public final class ClaimAudit {

    private ClaimAudit() {
    }

    public static String line(String event, Claim claim, String person, String user) {
        return line(event, claim, person, user, claim.getNumber());
    }

    static String line(String event, Claim claim, String person, String user, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records, after the change's own lines, each person whose figures the change moved, then the sheet's totals
 *  when they moved. */
public class AuditRollup {
    public void audit(@PathVariable("sheetId") String sheetId, @Val Rollup before, SheetRepository sheets,
            PersonRepository people, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        Rollup now = Rollup.of(sheetId, sheets, people, claims, rates, grades);
        now.changesSince(before, sheetId, AuditUser.decode(user)).forEach(audit::record);
    }
}

